import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter_blue_plus/flutter_blue_plus.dart';
import 'package:permission_handler/permission_handler.dart';

class BluetoothScanScreen extends StatefulWidget { const BluetoothScanScreen({super.key}); @override State<BluetoothScanScreen> createState()=>_BluetoothScanScreenState(); }
class _BluetoothScanScreenState extends State<BluetoothScanScreen>{List<ScanResult> results=[];bool scanning=false;String? message;StreamSubscription<List<ScanResult>>? sub;
 @override void initState(){super.initState();sub=FlutterBluePlus.scanResults.listen((r){if(mounted)setState(()=>results=r);});}
 Future<void> scan()async{try{final scanPermission=await Permission.bluetoothScan.request();final connectPermission=await Permission.bluetoothConnect.request();if(!scanPermission.isGranted||!connectPermission.isGranted){setState(()=>message='Allow Nearby devices permission in Android settings to scan.');return;}final supported=await FlutterBluePlus.isSupported;if(!supported){setState(()=>message='Bluetooth LE is not supported on this phone.');return;}final state=await FlutterBluePlus.adapterState.first;if(state!=BluetoothAdapterState.on){setState(()=>message='Turn on Bluetooth, then tap Scan again.');return;}setState((){results=[];message=null;scanning=true;});await FlutterBluePlus.startScan(timeout:const Duration(seconds:12));await Future.delayed(const Duration(seconds:12));if(mounted)setState(()=>scanning=false);}catch(e){if(mounted)setState(()=>message='Bluetooth scan failed: $e');}}
 @override void dispose(){sub?.cancel();FlutterBluePlus.stopScan();super.dispose();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Bluetooth devices')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Text('Find nearby Bluetooth Low Energy devices, including compatible BLE OBD adapters. Discovery does not mean the device is paired or that vehicle data is supported.'),const SizedBox(height:12),SizedBox(width:double.infinity,child:ElevatedButton(onPressed:scanning?null:scan,child:Text(scanning?'Scanning…':'Scan nearby devices'))),if(message!=null)Padding(padding:const EdgeInsets.all(12),child:Text(message!,style:const TextStyle(color:Colors.orangeAccent))),Expanded(child:results.isEmpty?Center(child:Text(scanning?'Searching for BLE devices…':'No devices found yet')):ListView.builder(itemCount:results.length,itemBuilder:(ctx,i){final r=results[i];final name=r.device.platformName.isNotEmpty?r.device.platformName:'Unknown BLE device';return ListTile(leading:const Icon(Icons.bluetooth),title:Text(name),subtitle:Text('${r.device.remoteId} · RSSI ${r.rssi} dBm'));}))])));
}
